export async function worker(path, { method = 'GET', body, raw } = {}) {
  if (!process.env.WORKER_URL || !process.env.WORKER_SECRET) throw Object.assign(new Error('Hosting worker is not configured'), { status: 503 });
  let r;
  try {
    r = await fetch(process.env.WORKER_URL + path, {
      method, cache: 'no-store',
      headers: { 'x-worker-secret': process.env.WORKER_SECRET, ...(raw ? { 'Content-Type': 'application/octet-stream' } : body ? { 'Content-Type': 'application/json' } : {}) },
      body: raw ?? (body ? JSON.stringify(body) : undefined),
    });
  } catch { throw Object.assign(new Error('Hosting worker unreachable'), { status: 502 }); }
  const data = await r.json().catch(() => ({}));
  if (!r.ok) throw Object.assign(new Error(data.error || 'Worker error'), { status: 502 });
  return data;
}

