import { HttpError } from './guard';
export function norm(k, v) {
  if (k === 'quiz') { let q; try { q = JSON.parse(v); } catch { throw new HttpError(400, 'quiz must be valid JSON'); } if (!Array.isArray(q)) throw new HttpError(400, 'quiz must be a JSON array'); return JSON.stringify(q); }
  if (k === 'banned') return v === true || v === 'true';
  if (['position', 'plan_id', 'max_servers', 'memory_mb', 'disk_mb'].includes(k)) { const n = parseInt(v, 10); if (Number.isNaN(n)) throw new HttpError(400, k + ' must be a number'); return n; }
  if (['cpu', 'price'].includes(k)) { const n = Number(v); if (Number.isNaN(n)) throw new HttpError(400, k + ' must be a number'); return n; }
  return String(v);
}

