import { getUser } from './auth';
export class HttpError extends Error { constructor(status, msg) { super(msg); this.status = status; } }
export async function needUser() { const u = await getUser(); if (!u) throw new HttpError(401, 'Login required'); return u; }
export async function needOwner() { const u = await needUser(); if (u.role !== 'owner') throw new HttpError(403, 'Forbidden'); return u; }
export const handle = (fn) => async (req, ctx) => {
  try { return await fn(req, ctx); }
  catch (e) {
    if (e.status) return Response.json({ error: e.message }, { status: e.status });
    if (e.code && String(e.code).startsWith('23')) return Response.json({ error: 'Invalid or duplicate data' }, { status: 400 });
    console.error(e); return Response.json({ error: 'Server error' }, { status: 500 });
  }
};

lib/crypto.js:
import crypto from 'crypto';
const key = () => {
  if (!process.env.ENCRYPTION_KEY) throw new Error('ENCRYPTION_KEY missing');
  return crypto.createHash('sha256').update(process.env.ENCRYPTION_KEY).digest();
};
export function enc(obj) {
  const iv = crypto.randomBytes(12); const c = crypto.createCipheriv('aes-256-gcm', key(), iv);
  const d = Buffer.concat([c.update(JSON.stringify(obj), 'utf8'), c.final()]);
  return [iv, c.getAuthTag(), d].map((b) => b.toString('base64')).join('.');
}
export function dec(s) {
  if (!s) return {};
  const [iv, tag, d] = s.split('.').map((x) => Buffer.from(x, 'base64'));
  const c = crypto.createDecipheriv('aes-256-gcm', key(), iv); c.setAuthTag(tag);
  return JSON.parse(Buffer.concat([c.update(d), c.final()]).toString('utf8'));
}

