import { SignJWT, jwtVerify } from 'jose';
import { cookies } from 'next/headers';
import { pool } from './db';
const secret = () => {
  if (!process.env.JWT_SECRET || process.env.JWT_SECRET.length < 16) throw new Error('JWT_SECRET must be set (16+ chars)');
  return new TextEncoder().encode(process.env.JWT_SECRET);
};
export async function createSession(uid) {
  const token = await new SignJWT({ uid }).setProtectedHeader({ alg: 'HS256' }).setExpirationTime('7d').sign(secret());
  cookies().set('session', token, { httpOnly: true, sameSite: 'lax', secure: process.env.NODE_ENV === 'production', path: '/', maxAge: 60 * 60 * 24 * 7 });
}
export function destroySession() { cookies().delete('session'); }
export async function getUser() {
  const token = cookies().get('session')?.value;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, secret());
    const { rows } = await pool.query('SELECT id, username, email, role, banned, avatar_url, plan_id FROM users WHERE id=$1', [payload.uid]);
    const u = rows[0];
    return u && !u.banned ? u : null;
  } catch { return null; }
}

