import { pool } from './db';
import { HttpError } from './guard';
export async function getPlan(userId) {
  const { rows } = await pool.query(
    `SELECT p.* FROM plans p WHERE p.id = COALESCE(
       (SELECT CASE WHEN u.plan_expires IS NULL OR u.plan_expires > now() THEN u.plan_id END FROM users u WHERE u.id=$1),
       (SELECT min(id) FROM plans))`, [userId]);
  return rows[0] || { id: 0, name: 'None', max_servers: 0, memory_mb: 256, cpu: 0.5, disk_mb: 500, price: 0 };
}
export async function own(id, u) {
  if (!/^\d{1,9}$/.test(String(id))) throw new HttpError(404, 'Not found');
  const { rows } = await pool.query('SELECT * FROM servers WHERE id=$1', [id]);
  const s = rows[0];
  if (!s || (s.user_id !== u.id && u.role !== 'owner')) throw new HttpError(404, 'Not found');
  return s;
}
export const log = (uid, action, detail = '') =>
  pool.query('INSERT INTO activity (user_id,action,detail) VALUES ($1,$2,$3)', [uid, action, String(detail).slice(0, 200)]).catch(() => {});

