db/schema.sql:
CREATE TABLE IF NOT EXISTS plans (
  id SERIAL PRIMARY KEY, name TEXT NOT NULL,
  max_servers INT NOT NULL DEFAULT 1, memory_mb INT NOT NULL DEFAULT 256,
  cpu NUMERIC NOT NULL DEFAULT 0.5, disk_mb INT NOT NULL DEFAULT 500, price NUMERIC NOT NULL DEFAULT 0
);
INSERT INTO plans (name) SELECT 'Free' WHERE NOT EXISTS (SELECT 1 FROM plans);
CREATE TABLE IF NOT EXISTS users (
  id SERIAL PRIMARY KEY, username TEXT UNIQUE NOT NULL, email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user', banned BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE users ADD COLUMN IF NOT EXISTS plan_id INT REFERENCES plans(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS plan_expires TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS avatar_url TEXT;
CREATE TABLE IF NOT EXISTS projects (
  id SERIAL PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',
  language TEXT, level TEXT, category TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE projects ADD COLUMN IF NOT EXISTS image_url TEXT, ADD COLUMN IF NOT EXISTS github_url TEXT,
  ADD COLUMN IF NOT EXISTS download_url TEXT, ADD COLUMN IF NOT EXISTS run_guide TEXT NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS code_preview TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS files TEXT NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS zip_path TEXT, ADD COLUMN IF NOT EXISTS downloads INT NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS lessons (
  id SERIAL PRIMARY KEY, title TEXT NOT NULL, language TEXT, level TEXT,
  content TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE lessons ADD COLUMN IF NOT EXISTS position INT NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS code TEXT NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS code_explain TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS playground TEXT NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS quiz JSONB NOT NULL DEFAULT '[]';
CREATE TABLE IF NOT EXISTS lesson_progress (
  user_id INT REFERENCES users(id) ON DELETE CASCADE, lesson_id INT REFERENCES lessons(id) ON DELETE CASCADE,
  done_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (user_id, lesson_id)
);
CREATE TABLE IF NOT EXISTS saved_projects (
  user_id INT REFERENCES users(id) ON DELETE CASCADE, project_id INT REFERENCES projects(id) ON DELETE CASCADE,
  PRIMARY KEY (user_id, project_id)
);
CREATE TABLE IF NOT EXISTS servers (
  id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL, runtime TEXT NOT NULL, start_cmd TEXT NOT NULL,
  env_enc TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'offline', created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS activity (
  id SERIAL PRIMARY KEY, user_id INT REFERENCES users(id) ON DELETE CASCADE,
  action TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
